import{z as i,x as n,o as s,c,q as t,j as B,D as r,d as e,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"精度与稳定性的案例与收束","description":"","frontmatter":{"title":"精度与稳定性的案例与收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sc-case-map.md","filePath":"cs/sc-case-map.md","lastUpdated":1791063341000}'),p={name:"cs/sc-case-map.md"};function d(m,a,f,h,u,C){const A=n("Mermaid");return s(),c("div",null,[a[2]||(a[2]=t('<h1 id="精度与稳定性的案例与收束" tabindex="-1">精度与稳定性的案例与收束 <a class="header-anchor" href="#精度与稳定性的案例与收束" aria-label="Permalink to &quot;精度与稳定性的案例与收束&quot;">​</a></h1><div class="epigraph"><p>数值事故很少死于不懂定理，多死于把三个可修的错叠在一起：公式、顺序与合同。</p><footer>—— 据 Goldberg, ACM Computing Surveys, 1991；Higham, Accuracy and Stability of Numerical Algorithms 整理</footer></div><p><a href="/cs/sc-optimizer-libraries">上一课</a>把优化库的合同对齐到四条轴，工具链至此配齐。本课是「数值与科学计算」的最后一课，用四个案例把全课程串成一条检查链：每个案例按同一格式过一遍——朴素写法、错在哪、修法与代价。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>案例课的风险是变成趣闻集，所以先钉串起它们的线，它正是主干与深钻共同的那条：先问映射的条件（<a href="/cs/condition-number">条件数</a>），再问算法注入的舍入（<a href="/cs/forward-backward-stability">前向稳定与后向稳定</a>），然后用精确块（<a href="/cs/sc-float-deep">浮点数的深入</a>）与运算组织（<a href="/cs/sc-blas-levels">BLAS 的层次</a>、<a href="/cs/sc-sparse-computing">稀疏计算</a>）修实现，外围靠工具链合同守住（<a href="/cs/sc-autodiff-implementation">自动微分的实现</a>、<a href="/cs/sc-optimizer-libraries">优化库的对照</a>、<a href="/cs/sc-random-generation">随机数生成</a>）。四案不是孤例，是这条链的四种走法。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>案例一，二次方程。</strong> 求根公式 \\(x=\\frac{-b\\pm\\sqrt{b^2-4ac}}{2a}\\)：当 \\(b\\gt 0\\) 且 \\(4ac\\ll b^2\\) 时，\\(-b+\\sqrt{\\cdots}\\) 是两个近的大数相减——减法本身精确（<a href="/cs/catastrophic-cancellation">消去与灾难抵消</a>），坏在两个操作数各带 \\(u\\) 级相对误差，相消后放大成大相对误差。修法：令 \\(q=-\\frac{b+\\mathrm{sign}(b)\\sqrt{b^2-4ac}}{2}\\)，两根为 \\(q/a\\) 与 \\(c/q\\)——韦达定理把危险的减法换成除法，代价是一次符号判断。</p><p><strong>案例二，方差。</strong> 单趟公式 \\(m_2-m^2\\)：数据在 \\(10^8\\) 附近、真方差 \\(10^2\\) 时，两项都是 \\(10^{16}\\) 量级，双精度相减只剩约三位有效，结果可以是负数。Welford 递推把大数相消从公式里拿掉：\\(\\bar x_k=\\bar x_{k-1}+\\frac{x_k-\\bar x_{k-1}}{k}\\)，平方和用增量更新（Welford, 1962；Chan, Golub 与 LeVeque, 1983 给过误差分析）。代价是循环串行——要并行就回到成对合并的账。</p><p><span class="marginnote">把案例二的账算开：均值 \\(10^8\\) 时 \\(m^2\\approx10^{16}\\)，双精度 \\(u\\approx1.1\\times10^{-16}\\)，一项的舍入误差就有 \\(1\\) 量级；两式相减剩下的方差若只有 \\(10^2\\)，绝对误差与之同量级——负方差不是奇观，是这个减法的正常输出。</span></p><p><strong>案例三，求和。</strong> \\(10^8\\) 个同号双精度数顺序求和，误差按 \\(\\gamma_n\\) 长到 \\(nu\\approx 10^{-8}\\) 的相对量级；成对求和压到 \\(u\\log n\\)，Kahan 补偿用 two-sum 把误差拿回到常数倍 \\(u\\)（<a href="/cs/summation-order">求和顺序</a>）。而库里的并行归约顺序不定——复现与性能的合同要自己钉（<a href="/cs/sc-blas-levels">BLAS 的层次</a>）。</p><p><strong>案例四，softmax。</strong> binary32 里 \\(\\exp(89)\\) 已上溢（\\(\\ln(3.4\\times10^{38})\\approx 88.7\\)）。先减最大值再取指数：数学上是恒等变换，数值上把溢出变成不可能；反向 VJP 用输出形式写，同样有界（<a href="/cs/sc-autodiff-implementation">自动微分的实现</a>）。</p><p><span class="marginnote">「条件数」是问题本身的属性，与算法无关——它告诉你这份输入下误差最多被放大多少倍；「稳定性」是算法的属性——好算法只注入与结果同量级的舍入。案例课反复用的正是这个分工：放大倍数改不了，注入量可以挑。</span></p>',12)),(s(),B(l,null,{default:r(()=>[o(A,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CASE%5B%22%E4%BA%8B%E6%95%85%E7%8E%B0%E5%9C%BA%22%5D%20--%3E%20COND%5B%22%E7%AC%AC%E4%B8%80%E6%AD%A5%EF%BC%9A%E6%98%A0%E5%B0%84%E7%9A%84%E6%9D%A1%E4%BB%B6%E6%95%B0%22%5D%0A%20%20COND%20--%3E%20INJ%5B%22%E7%AC%AC%E4%BA%8C%E6%AD%A5%EF%BC%9A%E7%AE%97%E6%B3%95%E6%B3%A8%E5%85%A5%E7%9A%84%E8%88%8D%E5%85%A5%22%5D%0A%20%20INJ%20--%3E%20FIX%5B%22%E7%AC%AC%E4%B8%89%E6%AD%A5%EF%BC%9A%E7%B2%BE%E7%A1%AE%E5%9D%97%E4%B8%8E%E8%BF%90%E7%AE%97%E7%BB%84%E7%BB%87%22%5D%0A%20%20FIX%20--%3E%20CONTRACT%5B%22%E7%AC%AC%E5%9B%9B%E6%AD%A5%EF%BC%9A%E5%B7%A5%E5%85%B7%E9%93%BE%E5%90%88%E5%90%8C%EF%BC%9AAD%E3%80%81%E5%BA%93%E3%80%81%E9%9A%8F%E6%9C%BA%E6%BA%90%22%5D%0A%20%20CONTRACT%20--%3E%20REP%5B%22%E5%8F%AF%E5%A4%8D%E7%8E%B0%E7%9A%84%E4%BF%AE%E6%B3%95%EF%BC%8C%E5%B8%A6%E4%BB%A3%E4%BB%B7%E7%9A%84%E7%BB%93%E8%AE%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("四案共享一个反直觉点：修法全部不减少误差的"),E("strong",null,"来源"),e("，只把误差从会被放大的位置挪到不会的位置——韦达把相消换成除法，Welford 把大数相消换成增量，成对求和把线性增长换成对数，减最大值把溢出换成平移。判断「挪到哪里」的依据始终是条件数与稳定性语言：这就是主干与深钻分层的原因——深钻给资源，主干给判据。反着用也成立：看到「加一个减最大值」「换一种求和树」这类补丁时，先问它挪走了哪一项放大，再决定要不要抄。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：数值修法像搬家不盖新房——误差一直都会产生（舍入躲不掉），修法只是把它从「会被放大器放大的入口」搬到「放大器够不着的角落」。放大器（条件数）还在原地，动的只是误差的落点。")],-1)),(s(),B(l,null,{default:r(()=>[o(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%7B%22%E8%A1%A5%E4%B8%81%E5%B1%9E%E4%BA%8E%E5%93%AA%E7%B1%BB%E4%BD%8D%E7%A7%BB%3F%22%7D%20--%3E%20A%5B%22%E9%9F%A6%E8%BE%BE%3A%20%E7%9B%B8%E6%B6%88%E5%87%8F%E6%B3%95%20%E2%86%92%20%E6%8D%A2%E6%88%90%E9%99%A4%E6%B3%95%22%5D%0A%20%20SUB%20--%3E%20B%5B%22Welford%3A%20%E5%A4%A7%E6%95%B0%E5%B9%B3%E6%96%B9%E5%B7%AE%20%E2%86%92%20%E6%8D%A2%E6%88%90%E5%A2%9E%E9%87%8F%22%5D%0A%20%20SUB%20--%3E%20C%5B%22%E6%88%90%E5%AF%B9%E6%B1%82%E5%92%8C%3A%20%E8%AF%AF%E5%B7%AE%E7%BA%BF%E6%80%A7%E9%95%BF%20%E2%86%92%20%E6%8D%A2%E6%88%90%E5%AF%B9%E6%95%B0%E9%95%BF%22%5D%0A%20%20SUB%20--%3E%20D%5B%22softmax%3A%20%E6%8C%87%E6%95%B0%E4%B8%8A%E6%BA%A2%20%E2%86%92%20%E6%8D%A2%E6%88%90%E5%B9%B3%E7%A7%BB%E5%90%8E%E6%81%92%E6%9C%89%E7%95%8C%22%5D%0A%20%20A%20--%3E%20PASS%5B%22%E8%90%BD%E7%82%B9%3A%20%E6%9D%A1%E4%BB%B6%E6%95%B0%E4%B8%8D%E5%86%8D%E6%94%BE%E5%A4%A7%E8%AF%A5%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20B%20--%3E%20PASS%0A%20%20C%20--%3E%20PASS%0A%20%20D%20--%3E%20PASS%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>这张图回答的问题是：四个案例的补丁为什么「看起来不像一类东西却是一类」——各自位移的操作不同，但落点相同：都把误差挪出条件数够得着的放大位置，这正是检查链第三步之前的共同判据。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不再引入新对象；后向稳定的证明、补偿求和的界、方差算法的误差分析都在引用课与出处文献里。四案之外没有万能清单——清单的价值在你肯把每一个新计算都过一遍这条链；跳过判据直接抄补丁，是这四案共同的另一种死法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二次方程：近量相减的下游才是事故；韦达把减法换成除法，代价一次判断。</li><li>方差：单趟平方和在量级悬殊时相消到负数；Welford 增量把相消从公式里拿掉。</li><li>求和：顺序误差随 \\(n\\) 线性长；成对压到对数、补偿拿回常数，复现靠钉顺序。</li><li>softmax：减最大值用恒等变换买断溢出，正向反向同时受益。</li><li>检查链：条件数、注入、精确块与组织、工具链合同，四案各走一遍。</li><li>出处：Goldberg, 1991；Higham；Welford, Technometrics, 1962；Chan, Golub and LeVeque, 1983。</li></ul>',5))])}const g=i(p,[["render",d]]);export{b as __pageData,g as default};
